      ctx.lineCap='butt';ctx.strokeStyle=steelD;ctx.lineWidth=w*1.12;ctx.beginPath();ctx.moveTo(bx,by);ctx.lineTo(tx,ty);ctx.stroke();ctx.strokeStyle=steel;ctx.lineWidth=w*0.82;ctx.beginPath();ctx.moveTo(bx-w*0.08,by);ctx.lineTo(tx-w*0.08,ty);ctx.stroke();
