    poly([F(bx0, by1, z0), F(bx1, by1, z0), F(bx1, by1, H), F(bx0, by1, H)], '#f4ecd8');
    poly([F(bx0, by1, r(0.15)), F(bx1, by1, r(0.15)), F(bx1, by1, H), F(bx0, by1, H)], accent);
    signBoard(-r(0.22), r(0.22), by1 + r(0.002), r(0.155), H - r(0.005), meta.sign, shade(accent, -0.2), '#ffffff');
