    poly([F(-r(0.068), by1, z0), F(r(0.068), by1, z0), F(r(0.068), by1, r(0.13)), F(-r(0.068), by1, r(0.13))], '#5a3a22');
    poly([F(-r(0.055), by1, z0 + r(0.006)), F(r(0.055), by1, z0 + r(0.006)), F(r(0.055), by1, r(0.122)), F(-r(0.055), by1, r(0.122))], '#8a5a33');
    drawWindow(-r(0.28), by1, r(0.048), r(0.068), r(0.075), '#86a8c0', '#ffffff', shade(accent, -0.25), true);
