    drawWindow(-r(0.30), by1, r(0.045), r(0.068), r(0.075), '#ffe9a0', '#ffffff', '#2f7a4a', true);
    drawWindow( r(0.30), by1, r(0.045), r(0.068), r(0.075), '#ffe9a0', '#ffffff', '#2f7a4a', true);
    const ov = r(0.045), rh = r(0.14), ridgeY = (by0 + by1) * 0.5;
    poly([F(bx0 - ov, by1 + ov, H - r(0.008)), F(bx1 + ov, by1 + ov, H - r(0.008)), F(bx1 + ov, ridgeY, H + rh), F(bx0 - ov, ridgeY, H + rh)], '#8a5a3a');
