    ctx.beginPath();
    ctx.moveTo(ob[0] - rrO * 0.85, ob[1]);
    ctx.bezierCurveTo(ob[0] - rrO * 1.45, ob[1] - r(0.045), ob[0] - rrO * 0.65, ob[1] - r(0.085), ob[0], ob[1] - r(0.14));
    ctx.bezierCurveTo(ob[0] + rrO * 0.65, ob[1] - r(0.085), ob[0] + rrO * 1.45, ob[1] - r(0.045), ob[0] + rrO * 0.85, ob[1]);
    ctx.closePath();
