    [-r(0.29), r(0.29)].forEach(mx => {
      const mp = F(mx, by1, r(0.088));
      ell(mp, r(0.044), r(0.046), '#8e8a72');
      disc([mp[0] - r(0.015), mp[1] - r(0.008)], r(0.009), '#2fbf9a');
      disc([mp[0] + r(0.015), mp[1] - r(0.008)], r(0.009), '#2fbf9a');
    });
    const ov = r(0.05), rh = r(0.145), ridgeY = (by0 + by1) * 0.5;
    poly([F(bx0 - ov, by1 + ov, H - r(0.01)), F(bx1 + ov, by1 + ov, H - r(0.01)), F(bx1 + ov * 0.5, ridgeY, H + rh), F(bx0 - ov * 0.5, ridgeY, H + rh)], '#b5893d');
