    drawWindow(-r(0.29), by1, r(0.048), r(0.078), r(0.078), '#38bdf8', '#0f172a', null, false);
    drawWindow( r(0.29), by1, r(0.048), r(0.078), r(0.078), '#38bdf8', '#0f172a', null, false);
