    poly([F(bx0 - r(0.03), by1 + r(0.02), H), F(bx1 + r(0.03), by1 + r(0.02), H), F(bx1 - r(0.08), ridgeY, H + r(0.115)), F(bx0 + r(0.08), ridgeY, H + r(0.115))], '#94a3b8');
    const dm = F(0, ridgeY, H + r(0.115));
    ell(dm, r(0.145), r(0.078), '#0284c7');
