    [-r(0.46), -r(0.16), r(0.16), r(0.46)].forEach(xp => line(F(xp, by1 + r(0.016), r(0.088)), F(xp, by1 + r(0.016), H), '#451a03', R * 0.011));
    poly([F(-r(0.072), by1, z0), F(r(0.072), by1, z0), F(r(0.072), by1, r(0.12)), F(0, by1, r(0.145)), F(-r(0.072), by1, r(0.12))], '#78350f');
