    [-r(0.29), 0, r(0.29)].forEach((ax, idx) => {
      poly([F(ax - r(0.078), by1, z0), F(ax + r(0.078), by1, z0), F(ax + r(0.078), by1, r(0.11)), F(ax, by1, r(0.14)), F(ax - r(0.078), by1, r(0.11))], idx === 1 ? '#78350f' : '#0284c7');
    });
    const ov = r(0.04), rh = r(0.125), ridgeY = (by0 + by1) * 0.5;
    poly([F(bx0 - ov, by1 + ov, H - r(0.008)), F(bx1 + ov, by1 + ov, H - r(0.008)), F(bx1 + ov, ridgeY, H + rh), F(bx0 - ov, ridgeY, H + rh)], '#c2410c');
