  // =========================================================================
  // 5. FRONT-ON PASSENGER BOARDING PLATFORM & SHELTER (Y from -0.02 to +0.22)
  //    (Building & platform only — no track or train!)
  // =========================================================================
  const py0 = -r(0.02), py1 = r(0.22), pz = r(0.050);
  const deckCol = (theme === 'western' || theme === 'frontier' || theme === 'nordic' || theme === 'tiki') ? '#b58858'
                : (theme === 'space' || theme === 'retro_future') ? '#cbd5e1'
                : (theme === 'gothic') ? '#52525b' : '#e2e8f0';
  const skirtCol = shade(deckCol, -0.32);
  const stripeCol = theme === 'standard' ? accent : meta.border;

  // Front vertical platform riser + horizontal platform deck + colored tactile safety strip
  poly([F(-r(0.56), py1, z0), F(r(0.56), py1, z0), F(r(0.56), py1, pz), F(-r(0.56), py1, pz)], skirtCol);
  poly([F(-r(0.56), py0, pz), F(r(0.56), py0, pz), F(r(0.56), py1, pz), F(-r(0.56), py1, pz)], deckCol);
